321:.payment-detail-row > .MuiTypography-root:first-child { color: #343434; font-size: .76rem; }
322:.payment-detail-row > .MuiTypography-root:last-child { min-width: 0; font-size: .76rem; font-weight: 650; overflow-wrap: anywhere; }
323:.payment-checksum { display: flex; align-items: center; gap: 5px; }
