325:.payment-detail-hrms-card .payment-detail-row { grid-template-columns: minmax(120px, 1fr) minmax(0, 1fr); }
326:.payment-detail-hrms-card .payment-detail-row > .MuiTypography-root:last-child { text-align: right; }
