(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  const consoleMsgs = [];
  page.on('console', (msg) => consoleMsgs.push(`[${msg.type()}] ${msg.text()}`));
  page.on('pageerror', (err) => consoleMsgs.push(`[pageerror] ${err.message}`));

  await page.goto('http://localhost:5173/login', { waitUntil: 'networkidle' });
  await page.fill('input[name="email"], input[type="email"]', 'manager@payroll.local');
  await page.fill('input[name="password"], input[type="password"]', 'Manager123!');
  await page.click('button[type="submit"]');
  await page.waitForURL('**/dashboard**', { timeout: 15000 }).catch(() => {});
  await page.waitForTimeout(1000);

  console.log('--- DASHBOARD TEXT ---');
  const dashText = await page.locator('.content-page').first().innerText().catch(() => '(not found)');
  console.log(dashText.slice(0, 2000));

  await page.goto('http://localhost:5173/payments/preview', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);

  const selectBox = page.locator('#preview-period-label').locator('xpath=following-sibling::div[contains(@class,"MuiSelect-select")]').first();
  const closedText = await page.locator('.MuiSelect-select').first().innerText().catch(() => '(not found)');
  console.log('--- CLOSED SELECT TEXT ---');
  console.log(closedText);

  await page.locator('.MuiSelect-select').first().click();
  await page.waitForTimeout(500);

  const menuItems = await page.locator('ul[role="listbox"] li').allInnerTexts();
  console.log('--- OPEN MENU ITEMS ---');
  menuItems.forEach((t, i) => console.log(i, JSON.stringify(t)));

  console.log('--- DUPLICATE CHECK ---');
  const counts = {};
  menuItems.forEach((t) => { counts[t] = (counts[t] || 0) + 1; });
  console.log(JSON.stringify(counts, null, 2));

  console.log('--- CONSOLE/PAGE ERRORS ---');
