1	import {
2	  ArrowForwardIosRounded,
3	  CalendarMonthRounded,
4	  DescriptionRounded,
5	  GroupsRounded,
6	  LinkRounded,
7	  MoreVertRounded,
8	  PaymentsRounded,
9	  PersonSearchRounded,
10	  ReceiptLongRounded,
11	  SyncRounded,
12	  WarningAmberRounded,
13	} from "@mui/icons-material";
14	import {
15	  Box,
16	  Card,
17	  CardContent,
18	  Chip,
19	  IconButton,
20	  Skeleton,
21	  Table,
22	  TableBody,
23	  TableCell,
24	  TableContainer,
25	  TableHead,
26	  TableRow,
27	  Typography,
28	} from "@mui/material";
29	import { useCallback, useEffect, useState } from "react";
30	import { useNavigate } from "react-router-dom";
31	import { getPaymentBatches, getPaymentStatistics } from "../api/paymentApi";
32	import { ErrorState, PageHeader, StatusChip } from "../components/CommonComponents";
33	import { formatCurrency, formatDateTime, getErrorMessage } from "../utils";
34	
35	const quickActions = [
36	  {
37	    title: "Prepare Payment",
38	    description: "Go to payment dashboard to process payroll",
39	    path: "/payments/preview",
40	    icon: <DescriptionRounded />,
41	  },
42	  {
43	    title: "Payment Batches",
44	    description: "View and manage all payment batches",
45	    path: "/payments",
46	    icon: <PaymentsRounded />,
47	  },
48	  {
49	    title: "Payslips",
50	    description: "Access and download employee payslips",
51	    path: "/payslips",
52	    icon: <PersonSearchRounded />,
53	  },
54	];
55	
56	const dashboardStatus = (status) => {
57	  if (status === "completed") return "completed";
58	  if (["generating", "generated", "hrms_sync_pending"].includes(status)) return "pending";
59	  if (status === "cancelled") return "no_payroll_lines";
60	  return status;
61	};
62	
63	const formatPayPeriodDate = (value) => {
64	  if (!value) return "Not available";
65	  return new Intl.DateTimeFormat("en-SG", {
66	    day: "numeric",
67	    month: "short",
68	    year: "numeric",
69	    timeZone: "UTC",
70	  }).format(new Date(`${value}T00:00:00Z`));
71	};
72	
73	const formatPeriodStatus = (status) => status
74	  ? status.split("_").map((word) => word[0].toUpperCase() + word.slice(1)).join(" ")
75	  : null;
76	
77	function DashboardSummaryCard({ icon, label, value, description, loading, badge, periodRange }) {
78	  return (
79	    <Card className={`dashboard-summary-card${periodRange ? " dashboard-summary-card-pay-period" : ""}`}>
80	      <CardContent>
81	        <Box className="dashboard-summary-icon" aria-hidden="true">{icon}</Box>
82	        <Box className="dashboard-summary-copy">
83	          <Typography className="dashboard-summary-label">{label}</Typography>
84	          {loading ? <Skeleton width={115} height={38} /> : periodRange ? (
85	            <Typography component="div" className="dashboard-summary-value dashboard-period-range">
86	              <span>{periodRange.start}</span>
87	              <span aria-hidden="true">–</span>
88	              <span>{periodRange.end}</span>
89	            </Typography>
90	          ) : <Typography className="dashboard-summary-value">{value}</Typography>}
91	          {badge && <Chip size="small" color="success" label={badge} className="dashboard-period-chip" />}
92	          <Typography className="dashboard-summary-description">{description}</Typography>
93	        </Box>
94	      </CardContent>
95	    </Card>
96	  );
97	}
98	
99	export default function DashboardPage() {
100	  const navigate = useNavigate();
101	  const [statistics, setStatistics] = useState(null);
102	  const [batches, setBatches] = useState([]);
103	  const [loading, setLoading] = useState(true);
104	  const [error, setError] = useState("");
105	
106	  const load = useCallback(async () => {
107	    setLoading(true);
108	    setError("");
109	    try {
110	      const [stats, batchResult] = await Promise.all([
111	        getPaymentStatistics(),
112	        getPaymentBatches({ limit: 100 }),
113	      ]);
114	      setStatistics(stats);
115	      setBatches(batchResult.rows || []);
116	    } catch (requestError) {
117	      setError(getErrorMessage(requestError, "Unable to load the operational Dashboard."));
118	    } finally {
119	      setLoading(false);
120	    }
121	  }, []);
122	
123	  useEffect(() => { load(); }, [load]);
124	
125	  const recentBatches = batches.slice(0, 3);
126	  const successfulSyncs = batches.filter((batch) => batch.hrmsSyncStatus === "completed" && batch.hrmsSyncedAt);
127	  const latestSuccessfulSync = successfulSyncs
128	    .map((batch) => batch.hrmsSyncedAt)
129	    .sort((a, b) => new Date(b) - new Date(a))[0];
130	  const latestPaymentBatch = batches.find((batch) => batch.status !== "cancelled");
131	  const pendingRetries = batches.filter((batch) => batch.hrmsSyncStatus === "failed" || batch.status === "hrms_sync_failed").length;
132	  const isHrmsConnected = batches.some((batch) => batch.hrmsSyncStatus === "completed");
133	  const summary = statistics?.summary;
134	  const currentPayPeriod = summary?.currentPayPeriod;
135	
136	  return (
137	    <Box className="page-enter content-page dashboard-page">
138	      <PageHeader title="Dashboard" subtitle="Monitor the payroll process and HRMS delivery across all pay periods." />
139	      {error && <ErrorState message={error} onRetry={load} />}
140	
141	      <Box className="dashboard-summary-grid">
142	        <DashboardSummaryCard
143	          icon={<GroupsRounded />}
144	          label="Total Staff"
145	          value={summary?.activeStaff ?? 0}
146	          description="Active employees in payroll"
147	          loading={loading}
148	        />
149	        <DashboardSummaryCard
150	          icon={<CalendarMonthRounded />}
151	          label="Current Pay Period"
152	          periodRange={currentPayPeriod ? {
153	            start: formatPayPeriodDate(currentPayPeriod.startDate),
154	            end: formatPayPeriodDate(currentPayPeriod.endDate),
155	          } : null}
156	          value="No active period"
157	          badge={formatPeriodStatus(currentPayPeriod?.status)}
158	          description={currentPayPeriod ? "Payroll in progress" : "No pay period covers today"}
159	          loading={loading}
160	        />
161	        <DashboardSummaryCard
162	          icon={<ReceiptLongRounded />}
163	          label="Payment Batches"
164	          value={summary?.currentYearBatchCount ?? 0}
165	          description="Generated this year"
166	          loading={loading}
167	        />
168	        <DashboardSummaryCard
169	          icon={<GroupsRounded />}
170	          label="Pending Approvals"
171	          value={summary?.pendingApprovals ?? 0}
172	          description="Awaiting manager approval"
173	          loading={loading}
174	        />
175	      </Box>
176	
177	      <Card className="dashboard-section-card dashboard-batches-card">
178	        <Box className="dashboard-section-heading">
179	          <Typography component="h2">Recent Payment Batches</Typography>
180	          <button type="button" className="dashboard-view-all" onClick={() => navigate("/payments")}>
181	            View All <ArrowForwardIosRounded />
182	          </button>
183	        </Box>
184	        <TableContainer>
