const now = new Date("2026-07-26T08:00:00.000Z");
const timestamp = (daysAgo) => new Date(now.getTime() - daysAgo * 86400000);

// Computed from the real system clock (not the fixed `now` above) so the Dashboard's
// "current pay period" always has one genuine period covering today, regardless of
