    try {
        await sequelize.authenticate();
        console.log("PostgreSQL Connected");
    } catch (error) {
        console.error("Unable to connect to PostgreSQL:", error.message);
        throw error;
    }
};

module.exports = {
    sequelize,
    connectDB
};

